This solution uses a simulation-guided local search. Candidate schedules are evaluated by a full simulation, and the best one found within the time limit is output.

**Initial schedule.** For each intersection, count the cars that use each incoming street. This counts only streets that are not the last street of a path, since cars never queue at the end of their last street. Streets with a count above zero are included, ordered by the time of the first car's arrival (or by count) and given duration 1. Ordering by earliest arrival at the light helps because many cars start there.

**Simulation.** Each street has a queue. At each second t, for every intersection with a schedule, compute the green street from `t mod cycle`. The head car of that street's queue crosses if it has arrived by t. Each street passes one car per second, which holds naturally since only one street per intersection is green.

A car that crosses at time t onto the next street arrives at its end at t+L. If that street is the car's last, the car finishes at t+L and scores F+(D−t−L) if that is ≤ D. Otherwise it joins the queue at t+L.

Arrivals are processed with buckets by time. At each tick t, first add the cars arriving at t to their queues (in a stable order), then process the green streets. Arriving cars have to be queued behind existing ones, and a car arriving at exactly t can cross at t.

Within one second, cars arriving at the same street at the same time are ordered by when they were scheduled. This is deterministic and approximates the statement. Initial cars are queued in input order. A car crossing at t is placed in the bucket for t+L, with L≥1, so it never affects the current tick.

**Cost.** Cost per simulation is about D × (active intersections) plus car movements. Iterating all scheduled intersections each tick could reach 10^4 × 10^5, which is too slow. Instead, track only the intersections that have cars waiting. Simpler: keep a list of streets with a non-empty queue, and for each check whether it is green. The number of such streets is at most V=1000, so each tick costs about 1000 operations. A simulation therefore costs at most about 10^7 operations, giving roughly 100 or more evaluations in a few seconds.

**Local search.** Randomly pick an intersection (using a fixed seed) and either swap two streets in its order or change a duration between 1 and 3. Keep the change if the score does not drop. Stop at about 8 seconds of wall time, which is deterministic enough in practice.

To keep the green lookup fast, each intersection stores its cycle length and a per-second lookup computed from the order and durations.

```cpp
#include <bits/stdc++.h>
using namespace std;
int D,I,S,V,F;
vector<int> sE,sL;vector<string> sN;
vector<vector<int>> path;
vector<vector<int>> ord,dur;
vector<int> cyc;
vector<vector<int>> cand;
long long sim(){
    vector<vector<pair<int,int>>> sched(I);
    // per street: offset start and dur
    vector<int> st(S,-1),du(S,0);
    for(int i=0;i<I;i++){int o=0;for(size_t k=0;k<ord[i].size();k++){st[ord[i][k]]=o;du[ord[i][k]]=dur[i][k];o+=dur[i][k];}cyc[i]=o;}
    vector<deque<int>> q(S);
    vector<int> pos(V,0);
    vector<vector<int>> bucket(D+2);
    for(int c=0;c<V;c++)q[path[c][0]].push_back(c);
    long long score=0;
    vector<int> active;vector<char> inA(S,0);
    for(int s=0;s<S;s++)if(!q[s].empty()){active.push_back(s);inA[s]=1;}
    for(int t=0;t<=D;t++){
        for(int c:bucket[t]){int s=path[c][pos[c]];q[s].push_back(c);if(!inA[s]){inA[s]=1;active.push_back(s);}}
        bucket[t].clear();
        vector<int> na;
        for(int s:active){
            if(q[s].empty()){inA[s]=0;continue;}
            na.push_back(s);
            if(st[s]<0)continue;
            int e=sE[s];int m=t%cyc[e];
            if(m>=st[s]&&m<st[s]+du[s]){
                int c=q[s].front();q[s].pop_front();
                pos[c]++;int ns=path[c][pos[c]];int at=t+sL[ns];
                if(at>D)continue;
                if(pos[c]==(int)path[c].size()-1){score+=F+(D-at);}
                else bucket[at].push_back(c);
            }
        }
        active.swap(na);
    }
    return score;
}
int main(){
    scanf("%d %d %d %d %d",&D,&I,&S,&V,&F);
    sE.resize(S);sL.resize(S);sN.resize(S);
    unordered_map<string,int> id;
    char buf[64];
    for(int i=0;i<S;i++){int b;scanf("%d %d %s %d",&b,&sE[i],buf,&sL[i]);sN[i]=buf;id[sN[i]]=i;}
    path.resize(V);
    vector<int> cnt(S,0);
    for(int c=0;c<V;c++){int p;scanf("%d",&p);path[c].resize(p);for(int j=0;j<p;j++){scanf("%s",buf);path[c][j]=id[buf];if(j<p-1)cnt[path[c][j]]++;}}
    ord.assign(I,{});dur.assign(I,{});cyc.assign(I,1);
    vector<vector<int>> in(I);
    for(int s=0;s<S;s++)if(cnt[s]>0)in[sE[s]].push_back(s);
    for(int i=0;i<I;i++){
        sort(in[i].begin(),in[i].end(),[&](int a,int b){return cnt[a]>cnt[b];});
        ord[i]=in[i];dur[i].assign(in[i].size(),1);
    }
    vector<int> act;
    for(int i=0;i<I;i++)if(!ord[i].empty())act.push_back(i);
    long long best=sim();
    auto start=chrono::steady_clock::now();
    mt19937 rng(12345);
    while(!act.empty()){
        double el=chrono::duration<double>(chrono::steady_clock::now()-start).count();
        if(el>7.0)break;
        int i=act[rng()%act.size()];
        int n=ord[i].size();
        auto so=ord[i];auto sd=dur[i];
        int r=rng()%3;
        if(r==0&&n>1){int a=rng()%n,b=rng()%n;swap(ord[i][a],ord[i][b]);swap(dur[i][a],dur[i][b]);}
        else if(r==1){int a=rng()%n;dur[i][a]=1+rng()%3;}
        else if(n>1){int a=rng()%n;int s=ord[i][a];int d=dur[i][a];ord[i].erase(ord[i].begin()+a);dur[i].erase(dur[i].begin()+a);int b=rng()%n;ord[i].insert(ord[i].begin()+b,s);dur[i].insert(dur[i].begin()+b,d);}
        long long sc=sim();
        if(sc>=best)best=sc;else{ord[i]=so;dur[i]=sd;}
    }
    printf("%d\n",(int)act.size());
    for(int i:act){
        printf("%d\n%d\n",i,(int)ord[i].size());
        for(size_t k=0;k<ord[i].size();k++)printf("%s %d\n",sN[ord[i][k]].c_str(),dur[i][k]);
    }
}
